const CACHE='rehab-v7';const ASSETS=['./','./index.html','./style.css','./app.js','./model.js','./storage.js','./sound.js','./icon.svg','./manifest.json',...Array.from({length:8},(_,i)=>'./assets/exercise-'+i+'.png'),...Array.from({length:8},(_,i)=>'./assets/illustrations/1950s/exercise-'+i+'.png'),'./assets/icon-192.png','./assets/icon-512.png'];self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)))});self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('rehab-')&&k!==CACHE).map(k=>caches.delete(k)))))});self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok&&r.type==='basic'){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request)))});
